def reference(inputs):
    return torch.relu(inputs['x'] * 1.25 + inputs['y'] * 0.75 - 0.125)

def run(inputs):
    # Latency-bound tiny tensor: cost is dominated by kernel launches and
    # intermediate allocations. Compute into a single fresh buffer with
    # out-of-place first op + in-place tails, so the op issues 4 kernels
    # (mul, add, sub, clamp_min) instead of 6 launches with a redundant clone.
    # x and y are never mutated; a new tensor is returned on every call.
    out = torch.mul(inputs['x'], 1.25)
    out.add_(inputs['y'], alpha=0.75)
    out.sub_(0.125)
    out.clamp_min_(0.0)
    return out

