def inputs_for(rows, cols):
    x = (torch.linspace(-2, 2, rows * cols, device='cuda', dtype=torch.float32) + 3).reshape(rows, cols)
    return {'x': x, 'y': x.flip(-1)}

def get_inputs():
    return inputs_for(32, 256)

def get_test_cases():
    return [
        {'name': 'minimal', 'category': 'minimal', 'inputs': inputs_for(1, 1)},
        {'name': 'representative', 'category': 'representative', 'inputs': get_inputs()},
        {'name': 'boundary', 'category': 'boundary', 'inputs': inputs_for(2, 32)},
        {'name': 'ragged', 'category': 'ragged', 'inputs': inputs_for(3, 17)},
    ]

def get_benchmark_inputs():
    return [{'name': 'primary', 'inputs': get_inputs()}, {'name': 'small', 'inputs': inputs_for(2, 32)}]

def reference(inputs):
    return torch.relu(inputs['x'] * 1.25 + inputs['y'] * 0.75 - 0.125)

# Cached 0-dim constants (per device/dtype) so no scalar tensor allocation or
# host->device transfer happens inside the timed path.
_CONSTS = {}

def _consts(device, dtype):
    key = (device, dtype)
    c = _CONSTS.get(key)
    if c is None:
        c = (
            torch.tensor(-0.125, device=device, dtype=dtype),
            torch.tensor(1.0, device=device, dtype=dtype),
        )
        _CONSTS[key] = c
    return c

def run(inputs):
    # relu(1.25*x + 0.75*y - 0.125) in three elementwise kernels, one allocation.
    #   k1: out = addcmul(c, x, one, value=1.25) -> 1.25*x - 0.125   (fused mul+sub)
    #   k2: out.add_(y, alpha=0.75)              -> 1.25*x + 0.75*y - 0.125
    #   k3: out.relu_()                          -> max(., 0), NaN-propagating like reference
    c, one = _consts(inputs['x'].device, inputs['x'].dtype)
    out = torch.addcmul(c, inputs['x'], one, value=1.25)
    out.add_(inputs['y'], alpha=0.75)
    out.relu_()
    return out

